package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.SettingRepository;

/** The due-by a claim of the person on the date is fixed with when it is created: the terms-th business day after its
 * date — skipping Saturdays, Sundays and the sheet's holidays (as the list stands now) — for the person's own terms,
 * else those of their grade, else the sheet's, each as in force on that date. */
public final class NewDueBy {

    private NewDueBy() {
    }

    public static LocalDate of(LocalDate date, Person person, SettingRepository settings,
            HolidayRepository holidays) {
        return holidays.businessDaysAfter(person.sheetId(), date,
                person.termsOn(settings.dated(person.sheetId()), date));
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** A new DRAFT claim; its due-by is fixed now: its date plus the person's own terms, else
 * those of their grade, else the sheet's, each as in force on that date. */
public class BuildClaim {
    public void build(@Val ClaimInput input, @Val Person person, SheetRepository sheets, SettingRepository settings,
            HolidayRepository holidays, Out<Claim> claim) {
        LocalDate date = input.date() != null ? input.date() : sheets.entryDate(person.sheetId());
        LocalDate dueBy = NewDueBy.of(date, person, settings, holidays);
        claim.set(new Claim(null, person.sheetId(), person.id(), input.amount(), date, input.note(), ClaimStatus.DRAFT,
                null, null, null, false, null, input.corrects(), dueBy));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class ApplyClaim {
    public void apply(@Val ClaimInput input, @Val Claim claim, SheetRepository sheets, Out<Claim> updated) {
        updated.set(new Claim(claim.id(), claim.sheetId(), claim.personId(), input.amount(),
                input.date() != null ? input.date() : sheets.entryDate(claim.sheetId()), input.note(), claim.status(),
                claim.number(), claim.due(), claim.openedBy(), claim.stated(), claim.statedDue(), input.corrects(),
                claim.dueBy(), claim.deferredUntil(), claim.proofs(), claim.splitFrom(), claim.added(), claim.waived()));
    }
}
package net.officefloor.hq.app.holiday;

import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.plugin.variable.Val;

/**
 * Works out again the due-by of every claim on the sheet that is not SETTLED or VOID and is due by on or after the new
 * holiday: from the claim's date, with the terms it was fixed with, over the holidays now on the sheet.
 */
public class RefixDueBys {
    public void refix(@Val Holiday holiday, ClaimRepository claims) {
        claims.refixDueBys(holiday.sheetId(), holiday.date());
    }
}

